"use client";
import { useEffect, useRef, useState } from "react";
import toast from "react-hot-toast";
import PageHeader from "@/components/PageHeader";
import ConfirmDialog from "@/components/ConfirmDialog";
import { useAuth } from "@/context/AuthContext";
import { api } from "@/lib/api";
import { CacheInspection } from "@/lib/types";
export default function CachePage() {
  const { activeWorkspace, activeProject } = useAuth();
  const scope = `${activeWorkspace?.id}/${activeProject?.id}`;
  const current = useRef(scope); current.current = scope;
  const [fingerprint, setFingerprint] = useState("");
  const [result, setResult] = useState<CacheInspection | null>(null);
  const [busy, setBusy] = useState("");
  const [error, setError] = useState("");
  const [model, setModel] = useState("");
  const [tags, setTags] = useState("");
  const [prompt, setPrompt] = useState("");
  const [completion, setCompletion] = useState("");
  const [warmModel, setWarmModel] = useState("gpt-4o-mini");
  const [confirm, setConfirm] = useState<"purge" | "delete" | null>(null);
  useEffect(() => { setResult(null); setFingerprint(""); setError(""); setConfirm(null); }, [scope]);
  async function execute(action: string) {
    if (!activeWorkspace || !activeProject) { setError("Select a workspace and project first."); return; }
    const requestScope = scope;
    setBusy(action); setError("");
    try {
      if (action === "inspect") { const data = await api.inspectCacheKey(fingerprint.trim()); if (current.current === requestScope) setResult(data); }
      if (action === "delete") { await api.deleteCacheKey(fingerprint.trim()); if (current.current === requestScope) setResult(null); toast.success("Cache object deleted."); }
      if (action === "purge") { const data = await api.purgeCache({ tenant_id: activeWorkspace.id, project_id: activeProject.id, model: model.trim() || undefined, tags: tags.split(",").map(t => t.trim()).filter(Boolean) }); toast.success(`Removed ${data.exact_keys_removed} exact keys and ${data.semantic_vectors_removed} semantic vectors.`); }
      if (action === "warm") { const data = await api.warmCache({ tenant_id: activeWorkspace.id, project_id: activeProject.id, items: [{ prompt: prompt.trim(), completion: completion.trim(), model: warmModel.trim() }] }); toast.success(`Seeded ${data.seeded} record(s).`); }
    } catch (e) { if (current.current === requestScope) setError(e instanceof Error ? e.message : "Cache operation failed."); }
    finally { setBusy(""); setConfirm(null); }
  }
  return <div><PageHeader index="03 / Cache" title="Semantic Memory Explorer" description="Inspect an exact fingerprint, warm a known response, or invalidate a selected scope." />{error && <div className="alert-error" role="alert">{error}</div>}<div className="grid grid-cols-1 lg:grid-cols-[1.2fr_1fr] gap-6"><div className="space-y-6"><section className="hairline-panel"><div className="panel-heading">01 / Object lookup</div><form className="p-6 space-y-4" onSubmit={e => { e.preventDefault(); execute("inspect"); }}><label className="label-caps block" htmlFor="fingerprint">SHA-256 fingerprint</label><input id="fingerprint" required value={fingerprint} onChange={e => setFingerprint(e.target.value)} className="input-field w-full" placeholder="Paste a request fingerprint" /><p className="text-xs text-on-surface-variant leading-6">Lookup uses the backend’s authenticated workspace scope. The current API does not expose a cache inventory.</p><button className="btn-secondary" disabled={!!busy}>{busy === "inspect" ? "Inspecting…" : "Inspect object"}</button></form></section><section className="hairline-panel"><div className="panel-heading">02 / Warm cache</div><form className="p-6 space-y-4" onSubmit={e => { e.preventDefault(); execute("warm"); }}><label htmlFor="warm-model" className="label-caps block">Model</label><input id="warm-model" className="input-field w-full" required value={warmModel} onChange={e => setWarmModel(e.target.value)} /><label htmlFor="warm-prompt" className="label-caps block">Original prompt</label><textarea id="warm-prompt" className="input-field w-full" rows={3} required value={prompt} onChange={e => setPrompt(e.target.value)} /><label htmlFor="warm-response" className="label-caps block">Cached response</label><textarea id="warm-response" className="input-field w-full" rows={4} required value={completion} onChange={e => setCompletion(e.target.value)} /><button className="btn-secondary" disabled={!!busy}>{busy === "warm" ? "Warming…" : "Warm cache"}</button></form></section><section className="hairline-panel"><div className="panel-heading">03 / Invalidate scope</div><form className="p-6 space-y-4" onSubmit={e => { e.preventDefault(); setConfirm("purge"); }}><label htmlFor="purge-model" className="label-caps block">Model filter / optional</label><input id="purge-model" className="input-field w-full" value={model} onChange={e => setModel(e.target.value)} /><label htmlFor="purge-tags" className="label-caps block">Tags / comma separated</label><input id="purge-tags" className="input-field w-full" value={tags} onChange={e => setTags(e.target.value)} /><p className="text-xs text-on-surface-variant">Scope: {activeWorkspace?.name} / {activeProject?.name}</p><button className="btn-secondary text-red-300" disabled={!!busy}>Review purge</button></form></section></div><section className="hairline-panel self-start lg:sticky lg:top-24"><div className="panel-heading">Cache object / inspection</div>{busy === "inspect" ? <div className="state-panel" role="status">Reading object…</div> : !result ? <div className="state-panel"><h3>SELECT A FINGERPRINT</h3><p>Object metadata and the cached payload will appear here after inspection.</p></div> : !result.found ? <div className="state-panel"><h3>OBJECT NOT FOUND</h3><p>The object may have expired or be outside your workspace.</p></div> : <div className="p-6 space-y-6"><dl className="grid grid-cols-2 gap-6 text-xs font-mono">{[["Model", result.model], ["TTL remaining", result.ttl_remaining_seconds == null ? undefined : `${result.ttl_remaining_seconds} s`], ["Access count", result.access_count], ["Created", result.created_at], ["Tokens saved", result.tokens_saved]].map(([label, value]) => <div key={label}><dt className="label-caps mb-2">{label}</dt><dd className="break-all">{value ?? "Unavailable"}</dd></div>)}</dl><div><h3 className="label-caps mb-3">Original prompt / preview</h3><pre className="surface-inset p-4 text-xs whitespace-pre-wrap break-words">{result.prompt_preview ?? "Unavailable"}</pre></div><div><h3 className="label-caps mb-3">Cached response / preview</h3><pre className="surface-inset p-4 text-xs whitespace-pre-wrap break-words">{result.response_preview ?? "Unavailable"}</pre></div><button className="btn-secondary text-red-300" disabled={!!busy} onClick={() => setConfirm("delete")}>Delete object</button></div>}</section></div>{confirm && <ConfirmDialog title={confirm === "purge" ? "Confirm scope purge" : "Confirm object deletion"} onClose={() => setConfirm(null)}><p className="text-sm text-on-surface-variant my-6">{confirm === "purge" ? `Remove matching cache records from ${activeWorkspace?.name} / ${activeProject?.name}?` : "Delete this cached response?"} This cannot be undone.</p><div className="flex gap-3"><button className="btn-secondary" onClick={() => setConfirm(null)}>Cancel</button><button className="btn-primary" disabled={!!busy} onClick={() => execute(confirm)}>{busy ? "Working…" : "Confirm removal"}</button></div></ConfirmDialog>}</div>;
}
